     1	// Price of a booking, in yen. Bookings of 4 hours or more get 10% off; members get 20% off on top.
     2	export const RATE_PER_HOUR = { small: 1200, large: 2600 };
     3	
     4	export function price({ room, start, end }, { member = false } = {}) {
     5	  const rate = RATE_PER_HOUR[room];
     6	  if (rate === undefined) throw new Error(`unknown room: ${room}`);
     7	  const hours = (end - start) / 60;
     8	  let total = rate * hours;
     9	  if (hours >= 4) total *= 0.9;
    10	  if (member) total *= 0.8;
    11	  return Math.round(total);
    12	}

