import { test } from 'node:test';
import assert from 'node:assert/strict';
import { book, cancel, createBook } from '../src/bookings.js';
import { countsByRoom, createWaitlist, join, leave, offerFreedSlot, waitingFor } from '../src/waitlist.js';

const people = (entries) => entries.map((e) => e.person);

// A booking of the small room on 2026-03-04 09:00-10:00 that was just cancelled.
function cancelledBooking() {
  const store = createBook();
  book(store, { room: 'small', slot: '2026-03-04 09:00-10:00', person: 'aki' });
  return cancel(store, 1);
}

test('the first person to join waits in position 1', () => {
  const list = createWaitlist();
  assert.deepEqual(join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' }), { ok: true, position: 1 });
});

test('nobody joins without a name', () => {
  const list = createWaitlist();
  assert.throws(() => join(list, { person: '', room: 'small', slot: '2026-03-04 09:00-10:00' }), { message: 'person is required' });
  assert.deepEqual(countsByRoom(list), {});
});

test('a person waits at most once for the same room and slot', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' });
  assert.deepEqual(join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' }), { ok: false, reason: 'already waiting' });
  assert.deepEqual(countsByRoom(list), { small: 1 });
  assert.equal(join(list, { person: 'mio', room: 'small', slot: '2026-03-04 13:00-14:00' }).ok, true);
  assert.equal(join(list, { person: 'mio', room: 'large', slot: '2026-03-04 09:00-10:00' }).ok, true);
  assert.deepEqual(countsByRoom(list), { small: 2, large: 1 });
});

test('the position counts the people who wait for that room at an overlapping time', () => {
  const list = createWaitlist();
