import { test } from 'node:test';
import assert from 'node:assert/strict';
import { book, cancel, createBook } from '../src/bookings.js';
import { countsByRoom, createWaitlist, join, leave, offerFreedSlot, waitingFor } from '../src/waitlist.js';

const people = (entries) => entries.map((e) => e.person);

// A booking of the small room on 2026-03-04 09:00-10:00 that was just cancelled.
function cancelledBooking() {
  const store = createBook();
  book(store, { room: 'small', slot: '2026-03-04 09:00-10:00', person: 'aki' });
  return cancel(store, 1);
}

test('the first person to join waits in position 1', () => {
  const list = createWaitlist();
  assert.deepEqual(join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' }), { ok: true, position: 1 });
});

test('nobody joins without a name', () => {
  const list = createWaitlist();
  assert.throws(() => join(list, { person: '', room: 'small', slot: '2026-03-04 09:00-10:00' }), { message: 'person is required' });
  assert.deepEqual(countsByRoom(list), {});
});

test('a person waits at most once for the same room and slot', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' });
  assert.deepEqual(join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' }), { ok: false, reason: 'already waiting' });
  assert.deepEqual(countsByRoom(list), { small: 1 });
  assert.equal(join(list, { person: 'mio', room: 'small', slot: '2026-03-04 13:00-14:00' }).ok, true);
  assert.equal(join(list, { person: 'mio', room: 'large', slot: '2026-03-04 09:00-10:00' }).ok, true);
  assert.deepEqual(countsByRoom(list), { small: 2, large: 1 });
});

test('the position counts the people who wait for that room at an overlapping time', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' });
  assert.deepEqual(join(list, { person: 'ken', room: 'small', slot: '2026-03-04 09:30-10:30' }), { ok: true, position: 2 });
  assert.deepEqual(join(list, { person: 'rin', room: 'large', slot: '2026-03-04 09:00-10:00' }), { ok: true, position: 1 });
  // 10:30-11:00 starts when ken's 09:30-10:30 ends: they touch, they do not overlap.
  assert.deepEqual(join(list, { person: 'sho', room: 'small', slot: '2026-03-04 10:30-11:00' }), { ok: true, position: 1 });
  assert.deepEqual(join(list, { person: 'emi', room: 'small', slot: '2026-03-04 09:45-10:45' }), { ok: true, position: 4 });
  assert.deepEqual(join(list, { person: 'yui', room: 'small', slot: '2026-03-05 09:00-10:00' }), { ok: true, position: 1 });
});

test('leaving takes the person off the waitlist of that room only', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' });
  join(list, { person: 'mio', room: 'large', slot: '2026-03-04 09:00-10:00' });
  join(list, { person: 'ken', room: 'small', slot: '2026-03-04 09:00-10:00' });
  assert.equal(leave(list, 'mio', 'small'), true);
  assert.deepEqual(countsByRoom(list), { small: 1, large: 1 });
  assert.deepEqual(people(waitingFor(list, 'small', { day: '2026-03-04', start: 540, end: 600 })), ['ken']);
});

test('leaving says when the person was not waiting', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' });
  assert.equal(leave(list, 'ken', 'small'), false);
  assert.equal(leave(list, 'mio', 'large'), false);
  assert.deepEqual(countsByRoom(list), { small: 1 });
});

test('the people waiting for a slot are those of the same room at an overlapping time, first come first', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:30-10:30' });
  join(list, { person: 'rin', room: 'large', slot: '2026-03-04 09:00-10:00' });
  join(list, { person: 'sho', room: 'small', slot: '2026-03-04 10:00-11:00' });
  join(list, { person: 'yui', room: 'small', slot: '2026-03-05 09:00-10:00' });
  join(list, { person: 'ken', room: 'small', slot: '2026-03-04 08:00-09:30' });
  assert.deepEqual(people(waitingFor(list, 'small', { day: '2026-03-04', start: 540, end: 600 })), ['mio', 'ken']);
  assert.deepEqual(people(waitingFor(list, 'small', { day: '2026-03-06', start: 540, end: 600 })), []);
});

test('a freed slot is offered to nobody when nobody waits for it', () => {
  const list = createWaitlist();
  join(list, { person: 'rin', room: 'large', slot: '2026-03-04 09:00-10:00' });
  join(list, { person: 'sho', room: 'small', slot: '2026-03-04 10:00-11:00' });
  assert.equal(offerFreedSlot(list, cancelledBooking()), null);
});

test('a freed slot is offered to the first person waiting, for 30 minutes', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:30-10:30' });
  join(list, { person: 'ken', room: 'small', slot: '2026-03-04 09:00-10:00' });
  const now = Date.parse('2026-03-03T12:00:00Z');
  assert.deepEqual(offerFreedSlot(list, cancelledBooking(), now), {
    to: 'mio',
    room: 'small',
    day: '2026-03-04',
    start: 540,
    end: 600,
    expiresAt: Date.parse('2026-03-03T12:30:00Z'),
  });
});

test('the 30 minutes of an offer run from the current time when no time is given', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' });
  const before = Date.now();
  const { expiresAt } = offerFreedSlot(list, cancelledBooking());
  const after = Date.now();
  const thirtyMinutes = 1_800_000;
  assert.ok(
    before + thirtyMinutes <= expiresAt && expiresAt <= after + thirtyMinutes,
    `expiresAt ${expiresAt} is not 30 minutes after the call (between ${before} and ${after})`,
  );
});

test('the people waiting are counted per room', () => {
  const list = createWaitlist();
  assert.deepEqual(countsByRoom(list), {});
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' });
  join(list, { person: 'ken', room: 'small', slot: '2026-03-04 13:00-14:00' });
  join(list, { person: 'rin', room: 'large', slot: '2026-03-04 09:00-10:00' });
  assert.deepEqual(countsByRoom(list), { small: 2, large: 1 });
});

test('the person who gets the offer is taken off the waitlist, for that entry only', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' });
  join(list, { person: 'ken', room: 'small', slot: '2026-03-04 09:30-10:30' });
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 13:00-14:00' });
  join(list, { person: 'mio', room: 'large', slot: '2026-03-04 09:00-10:00' });
  const cancelled = cancelledBooking();
  assert.equal(offerFreedSlot(list, cancelled).to, 'mio');
  assert.deepEqual(people(waitingFor(list, 'small', cancelled)), ['ken']);
  assert.deepEqual(countsByRoom(list), { small: 2, large: 1 });
  // mio declines the offer and joins again, now behind ken.
  assert.deepEqual(join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' }), { ok: true, position: 2 });
});

test('the next freed slot goes to the next person waiting', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' });
  join(list, { person: 'ken', room: 'small', slot: '2026-03-04 09:30-10:30' });
  const cancelled = cancelledBooking();
  assert.equal(offerFreedSlot(list, cancelled).to, 'mio');
  assert.equal(offerFreedSlot(list, cancelled).to, 'ken');
  assert.equal(offerFreedSlot(list, cancelled), null);
  assert.deepEqual(countsByRoom(list), {});
});

